CREATE TABLE tickets(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id),subject varchar(200) NOT NULL,category varchar(100) NOT NULL,priority varchar(20) NOT NULL DEFAULT 'normal',state varchar(30) NOT NULL DEFAULT 'open',assigned_to bigint REFERENCES admins(id),created_at bigint NOT NULL,updated_at bigint NOT NULL,revision integer NOT NULL DEFAULT 1);
CREATE INDEX tickets_owner ON tickets(user_id,updated_at DESC,id DESC);
CREATE INDEX tickets_queue ON tickets(state,updated_at DESC,id DESC);
CREATE TABLE ticket_messages(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ticket_id bigint NOT NULL REFERENCES tickets(id),admin_id bigint REFERENCES admins(id),body text NOT NULL,internal boolean NOT NULL DEFAULT false,created_at bigint NOT NULL);
CREATE INDEX ticket_history ON ticket_messages(ticket_id,id);
CREATE TABLE student_channels(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id bigint REFERENCES users(id),title varchar(160) NOT NULL,url varchar(255) NOT NULL UNIQUE,description text NOT NULL,status varchar(16) NOT NULL DEFAULT 'pending',created_at bigint NOT NULL,revision integer NOT NULL DEFAULT 1);
CREATE INDEX student_channels_listing ON student_channels(status,id DESC);
CREATE INDEX student_channels_owner ON student_channels(user_id,status);
CREATE TABLE personal_items(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id),kind varchar(20) NOT NULL,title varchar(200) NOT NULL,body text NOT NULL,day date NOT NULL,clock varchar(5) NOT NULL DEFAULT '',done boolean NOT NULL DEFAULT false,created_at bigint NOT NULL,updated_at bigint NOT NULL,revision integer NOT NULL DEFAULT 1);
CREATE INDEX personal_day ON personal_items(user_id,day,kind,clock,id);
CREATE TABLE listings(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id),title varchar(200) NOT NULL,body text NOT NULL,price bigint,category_id bigint REFERENCES taxonomy(id),file_id bigint REFERENCES files(id),contact varchar(300) NOT NULL,state varchar(30) NOT NULL DEFAULT 'pending',moderator_note varchar(1000) NOT NULL DEFAULT '',fingerprint varchar(64) NOT NULL,expires_at bigint NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,revision integer NOT NULL DEFAULT 1);
CREATE INDEX listings_public ON listings(state,expires_at,id DESC);
CREATE INDEX listings_owner ON listings(user_id,created_at DESC);
CREATE TABLE lost_items(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id),kind varchar(20) NOT NULL,title varchar(200) NOT NULL,body text NOT NULL,place varchar(200) NOT NULL,contact varchar(300) NOT NULL,state varchar(20) NOT NULL DEFAULT 'pending',note varchar(1000) NOT NULL DEFAULT '',revision integer NOT NULL DEFAULT 1,created_at bigint NOT NULL,updated_at bigint NOT NULL);
CREATE INDEX lost_public ON lost_items(state,id DESC);
CREATE INDEX lost_owner ON lost_items(user_id,created_at DESC);
CREATE TABLE reports(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id),content_id bigint REFERENCES contents(id),listing_id bigint REFERENCES listings(id),reason varchar(1000) NOT NULL,state varchar(20) NOT NULL DEFAULT 'open',created_at bigint NOT NULL);
CREATE INDEX reports_open ON reports(state,id);
CREATE TABLE student_limits(scope varchar(100) PRIMARY KEY,window_start bigint NOT NULL,hits integer NOT NULL);
INSERT INTO catalog_generations(scope) VALUES('leisure');
CREATE INDEX verified_student_lookup ON student_verifications(student_hash) WHERE status='approved';
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='unibot_app') THEN
 GRANT SELECT,INSERT,UPDATE,DELETE ON tickets,ticket_messages,student_channels,personal_items,listings,lost_items,reports,student_limits TO unibot_app;
 GRANT USAGE ON SEQUENCE tickets_id_seq,ticket_messages_id_seq,student_channels_id_seq,personal_items_id_seq,listings_id_seq,lost_items_id_seq,reports_id_seq TO unibot_app;
 GRANT INSERT,UPDATE ON settings TO unibot_app;
END IF;END $$;
CREATE TABLE content_topics(content_id bigint NOT NULL REFERENCES contents(id) ON DELETE CASCADE,topic_id bigint NOT NULL REFERENCES taxonomy(id),PRIMARY KEY(content_id,topic_id));
CREATE INDEX content_topics_lookup ON content_topics(topic_id,content_id);
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='unibot_app') THEN GRANT SELECT,INSERT,UPDATE,DELETE ON content_topics TO unibot_app; END IF; END $$;
-- Bound the entire dispatch, even when category membership changes between chunks.
ALTER TABLE announcement_dispatches ADD COLUMN enqueued_count integer NOT NULL DEFAULT 0;
